#!/usr/bin/env node
// Pre-renders the translated pages so search engines can index every language.
//
//   node scripts/build-i18n.js
//
// Source of truth is /index.html (English content + the `translations` object)
// and scripts/privacy-content.js. Writes /nl/index.html, /zh/index.html, the
// privacy page per language and /sitemap.xml. Re-run after editing either source
// and commit the generated files (GitHub Pages has no build step).

const fs = require('fs');
const path = require('path');
const privacy = require('./privacy-content');

const ROOT = path.resolve(__dirname, '..');
const SITE = 'https://www.ecovibe.space';

const LANG_NAMES = { en: 'English', nl: 'Nederlands', zh: '中文' };

// code: key in `translations`; lang: <html lang> / hreflang; dir: URL path
const LANGS = [
    { code: 'en', lang: 'en', dir: '', ogLocale: 'en_US' },
    { code: 'nl', lang: 'nl', dir: 'nl/', ogLocale: 'nl_NL' },
    { code: 'zh', lang: 'zh-Hans', dir: 'zh/', ogLocale: 'zh_CN' },
];

const source = fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8');
const translations = extractTranslations(source);
// Translatable markup lives before the first plain (non JSON-LD) <script>
const markupEnd = source.indexOf('<script>');

let mismatches = 0;
for (const l of LANGS) {
    const t = { ...translations.en, ...translations[l.code] };
    const html = l.code === 'en' ? checkEnglish(source, t) : render(source, l, t);
    if (l.dir) {
        fs.mkdirSync(path.join(ROOT, l.dir), { recursive: true });
        fs.writeFileSync(path.join(ROOT, l.dir, 'index.html'), html);
        console.log(`wrote ${l.dir}index.html`);
    }
}
for (const l of LANGS) {
    const dir = path.join(ROOT, l.dir, 'privacy');
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'index.html'), renderPrivacy(l));
    console.log(`wrote ${l.dir}privacy/index.html`);
}
fs.writeFileSync(path.join(ROOT, 'sitemap.xml'), sitemap(['', 'privacy/']));
console.log('wrote sitemap.xml');
if (mismatches) console.warn(`\n${mismatches} English text(s) in index.html differ from translations.en (see above)`);

// ───────────────────────────────────────────────────────

function extractTranslations(html) {
    const start = html.indexOf('const translations =');
    const end = html.indexOf('};', html.indexOf('\n        };', start)) + 1;
    if (start < 0 || end <= 0) throw new Error('translations object not found in index.html');
    const literal = html.slice(start + 'const translations ='.length, end);
    return new Function(`return (${literal});`)();
}

function render(html, l, t) {
    const url = SITE + '/' + l.dir;
    let body = replaceI18n(html.slice(0, markupEnd), t) + html.slice(markupEnd);

    body = body
        .replace('<!DOCTYPE html>', '<!DOCTYPE html>\n<!-- Generated by scripts/build-i18n.js from /index.html. Do not edit by hand. -->')
        .replace('<html lang="en">', `<html lang="${l.lang}">`)
        .replace(/<title>[^<]*<\/title>/, `<title>${escText(t['meta.title'])}</title>`)
        .replace(/(<meta name="description" content=")[^"]*/, `$1${escAttr(t['meta.description'])}`)
        .replace(/(<meta property="og:title" content=")[^"]*/, `$1${escAttr(t['meta.title'])}`)
        .replace(/(<meta property="og:description" content=")[^"]*/, `$1${escAttr(t['meta.description'])}`)
        .replace(/(<meta name="twitter:title" content=")[^"]*/, `$1${escAttr(t['meta.title'])}`)
        .replace(/(<meta name="twitter:description" content=")[^"]*/, `$1${escAttr(t['meta.description'])}`)
        .replace(/(<link rel="canonical" href=")[^"]*/, `$1${url}`)
        .replace(/(<meta property="og:url" content=")[^"]*/, `$1${url}`)
        .replace(/(<meta property="og:locale" content=")[^"]*/, `$1${l.ogLocale}`)
        .replace(/(<meta property="og:locale:alternate" content="[^"]*">\s*)+/, LANGS
            .filter(o => o !== l)
            .map(o => `<meta property="og:locale:alternate" content="${o.ogLocale}">`)
            .join('\n    ') + '\n    ')
        .replace(/(data-i18n-placeholder="([^"]+)" placeholder=")[^"]*/g,
            (m, pre, key) => pre + escAttr(t[key] ?? ''))
        .replace('href="/privacy/"', `href="/${l.dir}privacy/"`)
        .replace('<span id="currentLang">EN</span>', `<span id="currentLang">${l.code.toUpperCase()}</span>`);

    // Language switcher: mark this page's option as current
    body = body.replace(/<a class="lang-option( active)?" href="([^"]*)"([^>]*?) data-lang="(\w+)"( aria-current="page")?>/g,
        (m, active, href, attrs, code) => code === l.code
            ? `<a class="lang-option active" href="${href}"${attrs} data-lang="${code}" aria-current="page">`
            : `<a class="lang-option" href="${href}"${attrs} data-lang="${code}">`);

    return body;
}

// Replace the inner HTML of every element carrying data-i18n="key".
// Outer elements win when data-i18n elements are nested.
function replaceI18n(html, t) {
    const open = /<([a-zA-Z][\w-]*)\b[^>]*?\sdata-i18n="([^"]+)"[^>]*>/g;
    const edits = [];
    let m;
    while ((m = open.exec(html))) {
        const [, tag, key] = m;
        const innerStart = m.index + m[0].length;
        const innerEnd = findClose(html, tag, innerStart);
        if (key in t) edits.push({ start: m.index, innerStart, innerEnd, key });
        else console.warn(`missing translation: ${key}`);
    }
    let out = html;
    let floor = Infinity;
    for (const e of edits.reverse()) {
        if (e.innerEnd > floor) continue; // nested inside an element already replaced
        out = out.slice(0, e.innerStart) + t[e.key] + out.slice(e.innerEnd);
        floor = e.start;
    }
    return out;
}

function findClose(html, tag, from) {
    const re = new RegExp(`<(/?)${tag}\\b[^>]*>`, 'gi');
    re.lastIndex = from;
    let depth = 1;
    let m;
    while ((m = re.exec(html))) {
        depth += m[1] ? -1 : 1;
        if (depth === 0) return m.index;
    }
    throw new Error(`unclosed <${tag}> at offset ${from}`);
}

// The English page is hand-maintained; warn when its text drifts from translations.en
function checkEnglish(html, t) {
    const norm = s => s.replace(/\s+/g, ' ').trim();
    const rendered = replaceI18n(html.slice(0, markupEnd), t);
    const strip = s => norm(s.replace(/<[^>]+>/g, ' '));
    if (strip(rendered) !== strip(html.slice(0, markupEnd))) {
        const open = /\sdata-i18n="([^"]+)"[^>]*>/g;
        let m;
        while ((m = open.exec(html.slice(0, markupEnd)))) {
            const tagStart = html.lastIndexOf('<', m.index);
            const tag = html.slice(tagStart + 1).match(/^[\w-]+/)[0];
            const inner = html.slice(m.index + m[0].length, findClose(html, tag, m.index + m[0].length));
            if (strip(inner) !== strip(t[m[1]] ?? '')) {
                mismatches++;
                console.warn(`index.html "${m[1]}": "${strip(inner)}" vs translations.en "${strip(t[m[1]] ?? '')}"`);
            }
        }
    }
    return html;
}

function sitemap(pages) {
    const today = new Date().toISOString().slice(0, 10);
    const urls = pages.flatMap(page => {
        const alternates = LANGS
            .map(l => `    <xhtml:link rel="alternate" hreflang="${l.lang}" href="${SITE}/${l.dir}${page}"/>`)
            .concat(`    <xhtml:link rel="alternate" hreflang="x-default" href="${SITE}/${page}"/>`)
            .join('\n');
        return LANGS.map(l => `  <url>
    <loc>${SITE}/${l.dir}${page}</loc>
${alternates}
    <lastmod>${today}</lastmod>
  </url>`);
    }).join('\n');
    return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"
        xmlns:xhtml="http://www.w3.org/1999/xhtml">
${urls}
</urlset>
`;
}

// Standalone page using the site's tokens and fonts; content from privacy-content.js
function renderPrivacy(l) {
    const c = privacy[l.code];
    const url = `${SITE}/${l.dir}privacy/`;
    const hreflang = LANGS
        .map(o => `<link rel="alternate" hreflang="${o.lang}" href="${SITE}/${o.dir}privacy/">`)
        .concat(`<link rel="alternate" hreflang="x-default" href="${SITE}/privacy/">`)
        .join('\n    ');
    const switcher = LANGS
        .map(o => o === l
            ? `<span aria-current="page">${LANG_NAMES[o.code]}</span>`
            : `<a href="/${o.dir}privacy/" hreflang="${o.lang}" lang="${o.lang}">${LANG_NAMES[o.code]}</a>`)
        .join(' · ');
    return `<!DOCTYPE html>
<!-- Generated by scripts/build-i18n.js from scripts/privacy-content.js. Do not edit by hand. -->
<html lang="${l.lang}">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${escText(c.title)}</title>
    <meta name="description" content="${escAttr(c.description)}">
    <link rel="canonical" href="${url}">
    <meta name="robots" content="index, follow">
    ${hreflang}
    <meta property="og:type" content="website">
    <meta property="og:site_name" content="EcoVibe">
    <meta property="og:title" content="${escAttr(c.title)}">
    <meta property="og:description" content="${escAttr(c.description)}">
    <meta property="og:url" content="${url}">
    <meta property="og:image" content="${SITE}/og-image.png">
    <meta property="og:locale" content="${l.ogLocale}">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png">
    <link rel="icon" type="image/png" sizes="16x16" href="/favicon-16.png">
    <link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png">
    <link rel="manifest" href="/site.webmanifest">
    <meta name="theme-color" content="#F6F3EC">
    <style>
        :root {
            --paper: #F6F3EC;
            --ink: #12312B;
            --ink-soft: #4E5F59;
            --rule: #E2DCCF;
            --leaf-deep: #1F5C42;
            --font-display: 'Instrument Serif', 'Noto Serif SC', 'Songti SC', Georgia, serif;
            --font-body: 'Inter', 'PingFang SC', 'Microsoft YaHei', system-ui, sans-serif;
        }
        * { box-sizing: border-box; }
        body {
            margin: 0;
            font-family: var(--font-body);
            font-size: 1.0625rem;
            line-height: 1.65;
            color: var(--ink);
            background: var(--paper);
            -webkit-font-smoothing: antialiased;
        }
        a { color: var(--leaf-deep); }
        .wrap { max-width: 720px; margin: 0 auto; padding: 0 20px; }
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 16px;
            flex-wrap: wrap;
            padding: 24px 0;
            border-bottom: 1px solid var(--rule);
            font-size: 0.92rem;
        }
        header .brand { font-weight: 600; color: var(--ink); text-decoration: none; }
        header nav { color: var(--ink-soft); }
        main { padding: 48px 0 72px; }
        h1, h2 { font-family: var(--font-display); font-weight: 400; letter-spacing: -0.01em; }
        h1 { font-size: clamp(2.4rem, 6vw, 3.2rem); line-height: 1.05; margin: 0 0 8px; }
        h2 { font-size: 1.7rem; line-height: 1.15; margin: 40px 0 8px; }
        h3 { font-size: 1.05rem; margin: 24px 0 4px; }
        p, li { color: var(--ink-soft); }
        ul { padding-left: 1.2em; }
        .updated { font-size: 0.92rem; margin: 0 0 32px; }
        footer {
            border-top: 1px solid var(--rule);
            padding: 24px 0 40px;
            font-size: 0.9rem;
            color: var(--ink-soft);
        }
    </style>
</head>
<body>
    <div class="wrap">
        <header>
            <a class="brand" href="/${l.dir}">EcoVibe</a>
            <nav aria-label="Language">${switcher}</nav>
        </header>
        <main>
            <h1>${escText(c.heading)}</h1>
            <p class="updated">${escText(c.updatedLabel)}: <time datetime="${privacy.updated}">${privacy.updated}</time></p>
${c.body.trim()}
        </main>
        <footer>
            <p><a href="/${l.dir}">${escText(c.back)}</a></p>
            <p>EcoVibe · KVK 95066675 · <a href="mailto:info@ecovibe.space">info@ecovibe.space</a></p>
        </footer>
    </div>
</body>
</html>
`;
}

function escAttr(s) {
    return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function escText(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
